# Use jq to extract bash commands properly
grep '"name":"bash"' .state/sessions/history/s_1774192017526_470/session.jsonl | python3 -c "
import sys, json
for line in sys.stdin:
    try:
        d = json.loads(line.strip())
        # Navigate to the command
        if 'content' in d:
            for item in d.get('content', []):
                if isinstance(item, dict) and item.get('type') == 'tool_use' and item.get('name') == 'bash':
                    cmd = item.get('input', {}).get('command', '')[:200]
                    print(cmd)
    except:
        pass
" 2>/dev/null | head -20
